In TypeScript kann das Duck Typing-Prinzip mit dem `any`-Typ und der Verwendung von Typ-Assertionen umgesetzt werden. Das `any`-Typ ist ein flexibles Typ-Element, das eine Variable als beliebiges Objekt behandelt, unabhängig von seiner tatsächlichen Typen-Definition. Typ-Assertionen ermöglichen es, einer Variablen einen speziellen Typ zuzuweisen, ohne dass die Variable tatsächlich diesen Typen aufweist.

Hier ein Beispiel, wie Duck Typing in TypeScript umgesetzt werden kann:

```typescript
interface Duck {
  quack(): void;
  swim(): void;
}

class MallardDuck implements Duck {
  quack(): void {
    console.log("Quack, quack");
  }

  swim(): void {
    console.log("Swimming like a duck");
  }
}

class DecoyDuck {
  quack(): void {
    console.log("Quack");
  }

  swim(): void {
    console.log("Swimming");
  }
}

function makeDuck(duck: any): Duck {
  // Typ-Assertion, um das Objekt als Duck zu behandeln
  return <Duck>duck;
}

const mallard: Duck = new MallardDuck();
const decoy: Duck = new DecoyDuck();

const duck1: Duck = makeDuck(mallard);
duck1.quack(); // Quack, quack

const duck2: Duck = makeDuck(decoy);
duck2.quack(); // Quack
```

