Hier ist ein C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>

using namespace std;

int main() {
    string wordToCount; // Wort, das gezählt werden soll
    string fileName; // Name der Datei, die gelesen werden soll

    // Eingabe des Wortes und des Dateinamens
    cout << "Geben Sie das zu zählende Wort ein: ";
    cin >> wordToCount;
    cout << "Geben Sie den Dateinamen ein: ";
    cin >> fileName;

    // Öffnen der Datei
    ifstream file(fileName);

    // Prüfen, ob die Datei geöffnet werden konnte
    if (!file) {
        cerr << "Fehler: Die Datei konnte nicht geöffnet werden." << endl;
        return 1;
    }

    // Map zum Speichern der Vorkommnisse des Wortes
    map<string, int> wordCount;

    // Variablen für die Zeilenlese
    string line;
    size_t pos;

    // Zeilen lesen und Wort zählen
    while (getline(file, line)) {
        // Trennen der Wörter in der aktuellen Zeile
        size_t start = 0;
        while ((pos = line.find(" ", start)) != string::npos) {
            string word = line.substr(start, pos - start);
            // Wenn das aktuelle Wort mit dem zu zählenden Wort übereinstimmt, zählen wir es auf
            if (word == wordToCount) {
                wordCount[word]++;
            }
            start = pos + 1;
        }
        // Das letzte Wort der aktuellen Zeile zählen
        string lastWord = line.substr(start);
        if (lastWord == wordToCount) {
            wordCount[wordToCount]++;
        }
    }

    // Schließen der Datei
    file.close();

    // Ausgabe der Ergebnisse
    cout << "Das Wort \"" << wordToCount << "\" trat " << wordCount[wordToCount] << " Mal auf in der Datei " << fileName << endl;

    return 0;
}
```

Das Programm liest die Eingaben des zu zählenden Wortes und des Dateinamens vom Benutzer ein, öffnet die Datei und liest sie Zeile für Zeile ein. Für jede Zeile werden die Wörter getrennt und jedes Vorkommen des zu zählenden Wortes in der aktuellen Zeile wird gezählt und in einer Map gespeichert. Nach Abschluss der Leseoperation wird die Map ausgegeben, um die Gesamtanzahl der Vorkommnisse des Wortes in der Datei anzuzeigen. 

Achtung: Das Programm arbeitet davon aus, dass jedes Wort durch einen Leerzeichen getrennt ist. Wenn in der Datei andere Trennzeichen wie z.B. Tabulatoren oder Zeilenumbrüche zum Einsatz kommen, muss das Programm angepasst werden.

